CREATE DATABASE IF NOT EXISTS notary_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE notary_db;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL DEFAULT 'staff', status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status), INDEX(role)) ENGINE=InnoDB;
CREATE TABLE archives (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ref_number VARCHAR(100) NOT NULL UNIQUE, created_by INT UNSIGNED NULL, updated_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE archive_documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, archive_id INT UNSIGNED NOT NULL, slot_no TINYINT UNSIGNED NOT NULL, original_name VARCHAR(255) NOT NULL, file_path VARCHAR(255) NOT NULL, FOREIGN KEY(archive_id) REFERENCES archives(id) ON DELETE CASCADE, UNIQUE KEY archive_slot(archive_id,slot_no));
CREATE TABLE payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, archive_id INT UNSIGNED NOT NULL, sender_name VARCHAR(150) NOT NULL, sender_phone VARCHAR(50) NOT NULL, amount DECIMAL(12,2) NOT NULL, received_by INT UNSIGNED NULL, paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(archive_id) REFERENCES archives(id) ON DELETE CASCADE, FOREIGN KEY(received_by) REFERENCES users(id) ON DELETE SET NULL, UNIQUE KEY uq_payments_archive(archive_id), INDEX idx_payments_sender_name(sender_name), INDEX idx_payments_sender_phone(sender_phone), INDEX(paid_at));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, user_name_snapshot VARCHAR(150) NOT NULL, action VARCHAR(60) NOT NULL, entity_type VARCHAR(60) NULL, entity_id BIGINT UNSIGNED NULL, entity_ref VARCHAR(150) NULL, details TEXT NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(user_id), INDEX(action), INDEX(created_at), INDEX(entity_type,entity_id)) ENGINE=InnoDB;
